function createSettingsRuntime(settingsService, programmaticIncludePathsService) {
    return {
        CONFIG_KEYS: settingsService.CONFIG_KEYS,
        SETTINGS_REFRESH_CONFIG_KEYS: settingsService.SETTINGS_REFRESH_CONFIG_KEYS,
        CACHE_RESET_CONFIG_KEYS: settingsService.CACHE_RESET_CONFIG_KEYS,
        THEME_RECOMMENDATION_CONFIG_KEYS: settingsService.THEME_RECOMMENDATION_CONFIG_KEYS,
        HOVER_RELEVANT_CONFIG_KEYS: settingsService.HOVER_RELEVANT_CONFIG_KEYS,
        PERSISTENT_HOVER_RELEVANT_CONFIG_KEYS: settingsService.PERSISTENT_HOVER_RELEVANT_CONFIG_KEYS,
        VALIDATION_DIAGNOSTIC_CONFIG_KEYS: settingsService.VALIDATION_DIAGNOSTIC_CONFIG_KEYS,
        affectsAnyConfiguration: settingsService.affectsAnyConfiguration,
        refreshExtensionSettings: settingsService.refresh,
        matchesConfiguredPawnFileExtension: settingsService.matchesConfiguredPawnFileExtension,
        getPawnFileExtensions: settingsService.getPawnFileExtensions,
        getIncludeFileExtensions: settingsService.getIncludeFileExtensions,
        shouldDetectPawnLanguageByIncludes: settingsService.shouldDetectPawnLanguageByIncludes,
        getLiveValidationMode: settingsService.getLiveValidationMode,
        getLiveValidationIssueMode: settingsService.getLiveValidationIssueMode,
        shouldRunLiveValidationScanOnOpen: settingsService.shouldRunLiveValidationScanOnOpen,
        getUnusedStockValidationMode: settingsService.getUnusedStockValidationMode,
        getCallbackSignatureMode: settingsService.getCallbackSignatureMode,
        getIncludeValidationMode: settingsService.getIncludeValidationMode,
        getExternalIncludeWatchMode: settingsService.getExternalIncludeWatchMode,
        getHoverMode: settingsService.getHoverMode,
        getHoverContentMode: settingsService.getHoverContentMode,
        shouldShowThemeRecommendation: settingsService.shouldShowThemeRecommendation,
        getPersistentHoverMode: settingsService.getPersistentHoverMode,
        isPersistentHoverEnabled: settingsService.isPersistentHoverEnabled,
        isHoverGoToDefinitionLinksEnabled: settingsService.isHoverGoToDefinitionLinksEnabled,
        isPersistentIncludeDeclarationCacheEnabled: settingsService.isPersistentIncludeDeclarationCacheEnabled,
        getPersistentIncludeDeclarationCacheMaxBytes: settingsService.getPersistentIncludeDeclarationCacheMaxBytes,
        getGlobalIncludePaths: settingsService.getGlobalIncludePaths,
        getProjectLocalIncludePaths: settingsService.getProjectLocalIncludePaths,
        getProgrammaticIncludePaths: () => (
            typeof programmaticIncludePathsService?.getProgrammaticIncludePaths === 'function'
                ? (programmaticIncludePathsService.getProgrammaticIncludePaths() || [])
                : []
        )
    };
}

function createStateRuntime(state) {
    return {
        includeDocumentModelWarmCache: state.includeDocumentModelWarmCache,
        lastSavedDocumentVersions: state.lastSavedDocumentVersions,
        liveValidationTimers: state.liveValidationTimers,
        liveValidationFullResultCache: state.liveValidationFullResultCache,
        workspaceIncludeWatcherState: state.workspaceIncludeWatcherState
    };
}

function createCacheRuntime(documentSystemRuntime, documentStateRuntime) {
    return {
        summarizeDocumentEditImpact: documentSystemRuntime.summarizeDocumentEditImpact,
        resolveDocumentEditImpact: documentSystemRuntime.resolveDocumentEditImpact,
        recordDocumentEditImpact: documentSystemRuntime.recordDocumentEditImpact,
        invalidateDocumentCaches: documentSystemRuntime.invalidateDocumentCaches,
        resetCachesAndWarmActiveDocument: documentSystemRuntime.resetCachesAndWarmActiveDocument,
        bumpDependencyFreshnessVersion: documentStateRuntime.bumpDependencyFreshnessVersion
    };
}

function createSharedRuntimeBundle(sources) {
    const {
        t,
        syntaxPrelude,
        baseSyntaxRuntime,
        declarationSupportRuntime,
        analysisRuntime,
        preprocessorRuntime,
        documentStateRuntime,
        documentSystemRuntime
    } = sources;

    return {
        t,
        isPawnDocument: baseSyntaxRuntime.isPawnDocument,
        normalizeFsPath: syntaxPrelude.normalizeFsPath,
        isSameFilePath: syntaxPrelude.isSameFilePath,
        getDocumentTextAndResolver: baseSyntaxRuntime.getDocumentTextAndResolver,
        getIncludeNameFromLine: baseSyntaxRuntime.getIncludeNameFromLine,
        getPawnDocumentContext: documentSystemRuntime.getPawnDocumentContext,
        createPawnDocumentContextSession: documentSystemRuntime.createPawnDocumentContextSession,
        getFileSnapshot: documentSystemRuntime.getFileSnapshot,
        warmWorkspaceIncludeSources: documentSystemRuntime.warmWorkspaceIncludeSources,
        markWorkspaceIncludeSourcesDirty: documentSystemRuntime.markWorkspaceIncludeSourcesDirty,
        getConfiguredGlobalIncludeSources: documentSystemRuntime.getConfiguredGlobalIncludeSources,
        getProjectRootForFile: documentSystemRuntime.getProjectRootForFile,
        getSearchPaths: documentSystemRuntime.getSearchPaths,
        getNestedSearchPaths: documentSystemRuntime.getNestedSearchPaths,
        getIncludeCompletionEntries: documentSystemRuntime.getIncludeCompletionEntries,
        resolveInclude: documentSystemRuntime.resolveInclude,
        readNormalizedFileContent: documentStateRuntime.readNormalizedFileContent,
        getCtrlCharStateForContent: baseSyntaxRuntime.getCtrlCharStateForContent,
        scheduleWarmDocumentContext: documentSystemRuntime.scheduleWarmDocumentContext,
        clearAllScheduledWarmups: documentSystemRuntime.clearAllScheduledWarmups,
        warmDocumentContext: documentSystemRuntime.warmDocumentContext,
        warmIncludedDocumentModels: documentSystemRuntime.warmIncludedDocumentModels,
        getLookupTokenAtPosition: baseSyntaxRuntime.getLookupTokenAtPosition,
        isLinePositionInsideCommentOrString: baseSyntaxRuntime.isLinePositionInsideCommentOrString,
        findHeaderFunctionByNameAtPosition: analysisRuntime.findHeaderFunctionByNameAtPosition,
        findFunctionDeclarationNameContext: analysisRuntime.findFunctionDeclarationNameContext,
        findDefinitionContext: analysisRuntime.findDefinitionContext,
        findFunctionCallNameContext: analysisRuntime.findFunctionCallNameContext,
        findNestedParentCallNameContext: analysisRuntime.findNestedParentCallNameContext,
        getWordAtPosition: analysisRuntime.getWordAtPosition,
        findPreferredKnownCallContext: analysisRuntime.findPreferredKnownCallContext,
        getPreferredFunctionHoverMatch: analysisRuntime.getPreferredFunctionHoverMatch,
        hasIncludeFunctionTwin: declarationSupportRuntime.hasIncludeFunctionTwin,
        isKnownFunctionName: declarationSupportRuntime.isKnownFunctionName,
        isNearbyCallContext: analysisRuntime.isNearbyCallContext,
        isMeaningfulCallCursorPosition: analysisRuntime.isMeaningfulCallCursorPosition,
        isMeaningfulCallPosition: analysisRuntime.isMeaningfulCallPosition,
        findIndexedAccessContextAtPosition: analysisRuntime.findIndexedAccessContextAtPosition,
        buildIndexedAccessSelectionModel: analysisRuntime.buildIndexedAccessSelectionModel,
        resolveDefaultAccessSymbolName: analysisRuntime.resolveDefaultAccessSymbolName,
        findVariableDeclarationSpanInRange: analysisRuntime.findVariableDeclarationSpanInRange,
        shouldSuppressVariableDeclarationValidationInRange: analysisRuntime.shouldSuppressVariableDeclarationValidationInRange,
        isVariableDeclarationNameAtPosition: analysisRuntime.isVariableDeclarationNameAtPosition,
        isOriginalDeclarationHover: analysisRuntime.isOriginalDeclarationHover,
        buildCallArgLayout: analysisRuntime.buildCallArgLayout,
        collectCallArgumentIssues: analysisRuntime.collectCallArgumentIssues,
        getObjectLikeDefineTupleTexts: analysisRuntime.getObjectLikeDefineTupleTexts,
        expandObjectLikeDefineTupleCallArgs: analysisRuntime.expandObjectLikeDefineTupleCallArgs,
        expandObjectLikeDefineTupleArgPieces: analysisRuntime.expandObjectLikeDefineTupleArgPieces,
        hasExpandableObjectLikeDefineTupleArg: analysisRuntime.hasExpandableObjectLikeDefineTupleArg,
        createDocumentCallContextIndex: analysisRuntime.createDocumentCallContextIndex,
        createLazyCallContextOptions: analysisRuntime.createLazyCallContextOptions,
        collectInlineNamedCallContexts: analysisRuntime.collectInlineNamedCallContexts,
        extractCallSiteArgs: analysisRuntime.extractCallSiteArgs,
        findMatchingParenOffset: analysisRuntime.findMatchingParenOffset,
        findCallContext: analysisRuntime.findCallContext,
        findCallContexts: analysisRuntime.findCallContexts,
        splitTopLevel: baseSyntaxRuntime.splitTopLevel,
        splitTopLevelWithRanges: baseSyntaxRuntime.splitTopLevelWithRanges,
        stripRootTagCasts: baseSyntaxRuntime.stripRootTagCasts,
        parseTopLevelTernaryExpression: baseSyntaxRuntime.parseTopLevelTernaryExpression,
        parseWholeCallExpression: baseSyntaxRuntime.parseWholeCallExpression,
        parsePawnExpression: baseSyntaxRuntime.parsePawnExpression,
        looksLikePawnExpressionFragment: baseSyntaxRuntime.looksLikePawnExpressionFragment,
        parseFuncArgs: analysisRuntime.parseFuncArgs,
        collectEnumMemberSyntaxIssues: analysisRuntime.collectEnumMemberSyntaxIssues,
        collectVariableDeclarationSyntaxIssuesForLine: analysisRuntime.collectVariableDeclarationSyntaxIssuesForLine,
        isExplicitDeclarationStartLine: analysisRuntime.isExplicitDeclarationStartLine,
        parseParamMeta: analysisRuntime.parseParamMeta,
        isValidPawnParamDescriptor: analysisRuntime.isValidPawnParamDescriptor,
        parseOperatorOverloadToken: analysisRuntime.parseOperatorOverloadToken,
        parseDimsParts: analysisRuntime.parseDimsParts,
        collectOperatorOverloadPolicyIssues: analysisRuntime.collectOperatorOverloadPolicyIssues,
        parseDimSpec: analysisRuntime.parseDimSpec,
        parseBraceArrayLiteralExpression: baseSyntaxRuntime.parseBraceArrayLiteralExpression,
        parseBraceArrayLiteralExpressionDetailed: baseSyntaxRuntime.parseBraceArrayLiteralExpressionDetailed,
        parseIndexedAccessExpression: baseSyntaxRuntime.parseIndexedAccessExpression,
        createHoverTypeAnalysisCache: analysisRuntime.createHoverTypeAnalysisCache,
        inferCallReturnType: analysisRuntime.inferCallReturnType,
        inferArrayLikeCallReturnType: analysisRuntime.inferArrayLikeCallReturnType,
        getArrayShapeIssue: analysisRuntime.getArrayShapeIssue,
        explainArrayShapeIssue: analysisRuntime.explainArrayShapeIssue,
        explainArrayShapeDiagnosticIssue: analysisRuntime.explainArrayShapeDiagnosticIssue,
        inferArgType: analysisRuntime.inferArgType,
        inferArrayShapeActualType: analysisRuntime.inferArrayShapeActualType,
        getExpressionAssignableInfo: analysisRuntime.getExpressionAssignableInfo,
        isSyntacticAssignableExpression: analysisRuntime.isSyntacticAssignableExpression,
        findArrayMustBeIndexedIssue: analysisRuntime.findArrayMustBeIndexedIssue,
        getScalarAssignmentTagIssue: analysisRuntime.getScalarAssignmentTagIssue,
        stripTagCastsForValidation: analysisRuntime.stripTagCastsForValidation,
        unwrapExpressionForValidation: analysisRuntime.unwrapExpressionForValidation,
        stripTrailingSemicolon: analysisRuntime.stripTrailingSemicolon,
        findFirstNonWhitespaceIndex: analysisRuntime.findFirstNonWhitespaceIndex,
        findPreviousNonWhitespaceIndex: analysisRuntime.findPreviousNonWhitespaceIndex,
        findBalancedGroupEnd: analysisRuntime.findBalancedGroupEnd,
        classifyPawnStatementLine: analysisRuntime.classifyPawnStatementLine,
        countStructuralBraces: analysisRuntime.countStructuralBraces,
        findKeywordOccurrences: analysisRuntime.findKeywordOccurrences,
        skipInlineControlHeader: analysisRuntime.skipInlineControlHeader,
        hasUnclosedFunctionCallGroup: analysisRuntime.hasUnclosedFunctionCallGroup,
        isConstVariableDecl: analysisRuntime.isConstVariableDecl,
        isIdentifierStartChar: analysisRuntime.isIdentifierStartChar,
        isIdentifierContinueChar: analysisRuntime.isIdentifierContinueChar,
        isHexLiteralIdentifierTail: analysisRuntime.isHexLiteralIdentifierTail,
        normalizeEnumName: analysisRuntime.normalizeEnumName,
        getEnumItemCellSpan: analysisRuntime.getEnumItemCellSpan,
        inferEffectiveDimPartsFromValue: analysisRuntime.inferEffectiveDimPartsFromValue,
        getEffectiveDeclDimParts: analysisRuntime.getEffectiveDeclDimParts,
        findUnresolvedReferenceNames: analysisRuntime.findUnresolvedReferenceNames,
        resolveIndexedAccessValidationChain: analysisRuntime.resolveIndexedAccessValidationChain,
        analyzePreprocessorConditionExpression: preprocessorRuntime.analyzePreprocessorConditionExpression,
        knownPreprocessorDirectives: preprocessorRuntime.knownPreprocessorDirectives,
        parsePreprocessorDirectiveLine: preprocessorRuntime.parsePreprocessorDirectiveLine,
        getPreprocessorDirectivePayloadRange: preprocessorRuntime.getPreprocessorDirectivePayloadRange,
        collectPreprocessorDirectiveText: preprocessorRuntime.collectPreprocessorDirectiveText,
        parsePreprocessorSingleIdentifierPayload: preprocessorRuntime.parsePreprocessorSingleIdentifierPayload,
        parsePreprocessorDefineDirective: preprocessorRuntime.parsePreprocessorDefineDirective,
        getPreprocessorDirectiveIssues: preprocessorRuntime.getPreprocessorDirectiveIssues,
        evaluatePawnNumericExpr: analysisRuntime.evaluatePawnNumericExpr,
        explainTypeCompat: analysisRuntime.explainTypeCompat,
        explainParamDeclCompat: analysisRuntime.explainParamDeclCompat,
        explainIndexedAccessDimCompat: analysisRuntime.explainIndexedAccessDimCompat,
        collectIndexedAccessExpressionsFromLine: analysisRuntime.collectIndexedAccessExpressionsFromLine,
        computeLineDepths: baseSyntaxRuntime.computeLineDepths,
        computeFunctionRangeMaps: declarationSupportRuntime.computeFunctionRangeMaps,
        collectDeclarationText: declarationSupportRuntime.collectDeclarationText,
        getLabelDeclarationIssues: baseSyntaxRuntime.getLabelDeclarationIssues,
        parseLabelDeclaration: baseSyntaxRuntime.parseLabelDeclaration,
        collectGotoReferences: baseSyntaxRuntime.collectGotoReferences,
        parseFunctionStateSpecFromHeaderText: baseSyntaxRuntime.parseFunctionStateSpecFromHeaderText,
        parseStateStatement: baseSyntaxRuntime.parseStateStatement,
        collectFunctionStateIssues: baseSyntaxRuntime.collectFunctionStateIssues,
        areStatefulFunctionRedeclarationsAllowed: baseSyntaxRuntime.areStatefulFunctionRedeclarationsAllowed,
        getStateStatementIssues: baseSyntaxRuntime.getStateStatementIssues,
        getActiveCtrlChar: baseSyntaxRuntime.getActiveCtrlChar,
        stripLineComment: baseSyntaxRuntime.stripLineComment,
        isEscapedQuote: baseSyntaxRuntime.isEscapedQuote,
        normalizeExtensionList: baseSyntaxRuntime.normalizeExtensionList,
        normalizeLiveValidationIssueMode: baseSyntaxRuntime.normalizeLiveValidationIssueMode,
        areLiveValidationWarningsEnabled: baseSyntaxRuntime.areLiveValidationWarningsEnabled,
        getDocumentFingerprint: baseSyntaxRuntime.getDocumentFingerprint,
        isPawnIdentifierStartChar: baseSyntaxRuntime.isPawnIdentifierStartChar,
        isPawnIdentifierContinueChar: baseSyntaxRuntime.isPawnIdentifierContinueChar,
        isPawnIdentifierBoundaryChar: baseSyntaxRuntime.isPawnIdentifierBoundaryChar,
        extractEnumSymbolName: declarationSupportRuntime.extractEnumSymbolName,
        getEnumDeclsForVariableDims: declarationSupportRuntime.getEnumDeclsForVariableDims,
        buildEnumMemberLine: declarationSupportRuntime.buildEnumMemberLine,
        getVariableInitializerUsageText: declarationSupportRuntime.getVariableInitializerUsageText,
        buildSig: declarationSupportRuntime.buildSig,
        measurePawnStringLiteral: baseSyntaxRuntime.measurePawnStringLiteral,
        isFunctionLikeDefineDecl: declarationSupportRuntime.isFunctionLikeDefineDecl,
        isFunctionLikeDecl: declarationSupportRuntime.isFunctionLikeDecl,
        collectWordDeclMatches: declarationSupportRuntime.collectWordDeclMatches,
        getDeclMatchKey: declarationSupportRuntime.getDeclMatchKey,
        finalizeDeclMatches: declarationSupportRuntime.finalizeDeclMatches,
        findFirstNavigableDecl: declarationSupportRuntime.findFirstNavigableDecl,
        BUILTIN_DECLS: syntaxPrelude.BUILTIN_DECLS,
        FORBIDDEN: syntaxPrelude.FORBIDDEN,
        getLiveValidationFullCacheKey: documentStateRuntime.getLiveValidationFullCacheKey,
        buildDependencyStampMap: documentStateRuntime.buildDependencyStampMap,
        getDependencyFreshnessVersion: documentStateRuntime.getDependencyFreshnessVersion,
        areDependencyStampsFresh: documentStateRuntime.areDependencyStampsFresh,
        invalidateFileStamp: documentStateRuntime.invalidateFileStamp,
        clearPersistentIncludeDeclCache: documentSystemRuntime.clearPersistentIncludeDeclCache,
        prunePersistentIncludeDeclCache: documentSystemRuntime.prunePersistentIncludeDeclCache
    };
}

function createCoreRuntimeBundle(sources) {
    return {
        settingsRuntime: createSettingsRuntime(sources.settingsService, sources.programmaticIncludePathsService),
        stateRuntime: createStateRuntime(sources.state),
        cacheRuntime: createCacheRuntime(sources.documentSystemRuntime, sources.documentStateRuntime),
        sharedRuntime: createSharedRuntimeBundle(sources)
    };
}

module.exports = { createCoreRuntimeBundle };
